import type { Metadata } from "next";

import { SiteFooter, SiteHeader } from "@/components/shell/site-chrome";
import { TripLoader } from "@/components/trip/trip-loader";

export const metadata: Metadata = {
  title: "Your trip",
  // Plans are private to the visitor's browser; there is nothing to index.
  robots: { index: false, follow: false },
};

/**
 * `params` is a Promise in Next 16 — synchronous access was removed, not
 * deprecated. The typed `PageProps` helper is generated by `next typegen`.
 */
export default async function TripPage({
  params,
}: PageProps<"/trip/[tripId]">) {
  const { tripId } = await params;

  return (
    <>
      <SiteHeader />
      <TripLoader tripId={tripId} />
      <SiteFooter />
    </>
  );
}
